package com.yihe.framework.ehr;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Deterministic identity suggestions; binding changes require an explicit audited human action. */
@Service
public class ReportMatchingService {
    static final String RULE="report-identity-rules-v1";
    final EhrRepository db;final EhrService ehr;
    public ReportMatchingService(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;}
    static String norm(Object value){return str(value).trim().replaceAll("[\\s\\u3000]+","").toLowerCase(Locale.ROOT);}
    @SuppressWarnings("unchecked") Map<String,Object> identity(Object encoded){
        Map<String,Object> fields=new LinkedHashMap<>();Map<String,Set<String>> values=new HashMap<>();List<String> conflicts=new ArrayList<>();
        Object parsed=ehr.decode(encoded);if(parsed instanceof List)for(Object item:(List<?>)parsed){if(!(item instanceof Map))continue;Map<String,Object> f=(Map<String,Object>)item;String key=str(f.get("field_key")),value=str(f.get("value_raw")).trim();if(value.isEmpty())continue;fields.put(key,value);values.computeIfAbsent(key,k->new HashSet<>()).add(norm(value));}
        for(Map.Entry<String,Set<String>> item:values.entrySet())if(item.getValue().size()>1&&Arrays.asList("full_name","employee_number","phone","identity_number").contains(item.getKey()))conflicts.add(item.getKey());
        fields.put("conflicts",conflicts);return fields;
    }
    List<Map<String,Object>> employees(EhrActor actor){
        require(!actor.mobile,403,"仅供后台管理使用");
        return db.all("SELECT r.record_id id,p.employee_name name,p.employee_no code,p.organization_name organization,p.team_name team,p.position_name job,p.phone,p.row_version profileVersion FROM a_health_records r JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE r.scope_code=? AND r.data_mode=? AND p.deleted_at IS NULL ORDER BY p.employee_no,r.record_id",actor.scope,actor.mode);
    }
    static Map<String,Object> publicEmployee(Map<String,Object> row){return map("id",row.get("id"),"name",row.get("name"),"code",row.get("code"),"organization",row.get("organization"),"team",row.get("team"),"job",row.get("job"),"profileVersion",row.get("profileVersion"));}
    public List<Map<String,Object>> searchEmployees(EhrActor actor,String query){String search=norm(query);require(search.length()<=100,422,"搜索内容过长");List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> p:employees(actor))if(search.isEmpty()||norm(p.get("name")).contains(search)||norm(p.get("code")).contains(search)){result.add(publicEmployee(p));if(result.size()==50)break;}return result;}
    @SuppressWarnings("unchecked") List<Map<String,Object>> candidates(Map<String,Object> fields,List<Map<String,Object>> people){
        String name=norm(fields.get("full_name")),code=norm(fields.get("employee_number")),phone=norm(fields.get("phone")),org=norm(fields.get("employer")),team=norm(fields.get("workshop"));boolean conflict=!((List<?>)fields.get("conflicts")).isEmpty();List<Map<String,Object>> rows=new ArrayList<>();
        for(Map<String,Object> p:people){boolean sameName=!name.isEmpty()&&name.equals(p.get("nameKey")),sameCode=!code.isEmpty()&&code.equals(p.get("codeKey")),samePhone=!phone.isEmpty()&&phone.equals(p.get("phoneKey"));if(!sameName&&!sameCode&&!samePhone)continue;
            List<String> evidence=new ArrayList<>();int score=0;if(sameName){score+=30;evidence.add("姓名一致");}if(sameCode){score+=60;evidence.add("工号一致");}if(samePhone){score+=60;evidence.add("手机号一致");}if(!org.isEmpty()&&org.equals(p.get("orgKey"))){score+=5;evidence.add("单位一致");}if(!team.isEmpty()&&team.equals(p.get("teamKey"))){score+=5;evidence.add("班组一致");}
            boolean identityConflict=(!name.isEmpty()&&!sameName)||(!code.isEmpty()&&!sameCode)||(!phone.isEmpty()&&!samePhone);
            Map<String,Object> row=publicEmployee(p);row.put("score",Math.min(100,score));row.put("evidence",evidence);row.put("exact",sameName&&(sameCode||samePhone)&&!conflict&&!identityConflict);row.put("identityConflict",identityConflict);row.put("nameConflict",!name.isEmpty()&&!sameName);rows.add(row);
        }
        rows.sort((a,b)->{int score=Integer.compare(num(b.get("score")),num(a.get("score")));return score==0?str(a.get("code")).compareTo(str(b.get("code"))):score;});return rows;
    }
    List<Map<String,Object>> preparedEmployees(EhrActor actor){List<Map<String,Object>> result=employees(actor);for(Map<String,Object> p:result)for(String[] pair:new String[][]{{"name","nameKey"},{"code","codeKey"},{"phone","phoneKey"},{"organization","orgKey"},{"team","teamKey"}})p.put(pair[1],norm(p.get(pair[0])));return result;}
    static String masked(Object value){String text=str(value);return text.length()<7?(text.isEmpty()?"":text.charAt(0)+"***"):text.substring(0,Math.min(4,text.length()))+"********"+text.substring(text.length()-4);}
    String fingerprint(Map<String,Object> row){return hex(digest(bytes(ehr.encode(map("id",row.get("id"),"revision",row.get("revision"),"recordId",row.get("recordId"),"fields",row.get("fields"),"examDate",row.get("examDate"),"institution",row.get("institution"))))));}
    String etag(Map<String,Object> row,Map<String,Object> saved){return hex(digest(bytes(fingerprint(row)+":"+(saved==null?0:num(saved.get("row_version"))))));}
    List<Map<String,Object>> reportRows(EhrActor actor){require(!actor.mobile,403,"仅供后台管理使用");return db.all("SELECT h.report_id id,h.revision,h.record_id recordId,h.field_values fields,h.review_status reviewStatus,h.institution_raw institution,COALESCE(h.exam_date_verified,h.exam_date_raw) examDate,h.created_at uploadedAt,s.source_file_id sourceId,(SELECT u.original_file_name FROM a_report_upload_metadata u WHERE u.source_file_id=s.source_file_id ORDER BY u.uploaded_at DESC LIMIT 1) fileName,(SELECT u.upload_channel FROM a_report_upload_metadata u WHERE u.source_file_id=s.source_file_id ORDER BY u.uploaded_at DESC LIMIT 1) channel,EXISTS(SELECT 1 FROM a_report_publications pub WHERE pub.report_id=h.report_id AND pub.revision=h.revision) published FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision JOIN a_health_records r ON r.record_id=h.record_id AND r.scope_code=h.scope_code AND r.data_mode=h.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE h.scope_code=? AND h.data_mode=? AND p.deleted_at IS NULL ORDER BY h.created_at DESC,h.report_id DESC",actor.scope,actor.mode);}
    Map<String,Object> saved(EhrActor actor,String id,int revision,boolean lock){return db.one("SELECT * FROM a_report_matching WHERE scope_code=? AND data_mode=? AND report_id=? AND revision=?"+(lock?" FOR UPDATE":""),actor.scope,actor.mode,id,revision);}
    Map<String,Object> enrich(Map<String,Object> row,Map<String,Object> saved,List<Map<String,Object>> people){Map<String,Object> fields=identity(row.get("fields"));List<Map<String,Object>> matches=candidates(fields,people);Map<String,Object> current=people.stream().filter(p->str(p.get("id")).equals(str(row.get("recordId")))).findFirst().orElse(null);String state;
        boolean locked=num(row.get("published"))==1||Arrays.asList("confirmed","rejected").contains(str(row.get("reviewStatus")));
        boolean valid=saved!=null&&fingerprint(row).equals(saved.get("report_digest"));
        if(locked)state=num(row.get("published"))==1?"archived":"locked";
        else if(valid&&"confirmed".equals(saved.get("matching_state"))&&str(row.get("recordId")).equals(saved.get("selected_record_id"))&&current!=null&&num(current.get("profileVersion"))==num(saved.get("selected_profile_version")))state="confirmed";
        else if(valid&&"unmatched".equals(saved.get("matching_state")))state="none";
        else if(valid&&"flagged".equals(saved.get("matching_state")))state="flagged";
        else if(matches.stream().filter(c->Boolean.TRUE.equals(c.get("exact"))).count()==1)state="exact";
        else state=matches.isEmpty()?"none":"similar";
        Map<String,Object> output=new LinkedHashMap<>(row);output.remove("fields");output.put("ocr",map("name",fields.get("full_name"),"code",fields.get("employee_number"),"identity",masked(fields.get("identity_number")),"phone",masked(fields.get("phone")),"conflicts",fields.get("conflicts")));output.put("matchStatus",state);output.put("candidates",matches.subList(0,Math.min(5,matches.size())));output.put("candidateCount",matches.size());output.put("currentEmployee",current==null?null:publicEmployee(current));output.put("etag",etag(row,saved));output.put("locked",locked);output.put("savedSelection",valid?saved==null?null:saved.get("selected_record_id"):null);return output;
    }
    public Map<String,Object> list(EhrActor actor,Map<String,String> query){List<Map<String,Object>> people=preparedEmployees(actor);Map<String,Map<String,Object>> history=new HashMap<>();for(Map<String,Object> m:db.all("SELECT * FROM a_report_matching WHERE scope_code=? AND data_mode=?",actor.scope,actor.mode))history.put(m.get("report_id")+":"+m.get("revision"),m);
        String search=norm(query.get("search")),status=str(query.get("status")),channel=str(query.get("channel")),from=str(query.get("from")),to=str(query.get("to"));require(search.length()<=100,422,"搜索内容过长");for(String date:Arrays.asList(from,to))if(!date.isEmpty())try{java.time.LocalDate.parse(date);}catch(Exception error){throw new EhrException(422,"日期格式不正确");}
        require(status.isEmpty()||Arrays.asList("all","pending","exact","similar","none","flagged","confirmed","archived","locked","matched").contains(status),422,"匹配状态不正确");List<Map<String,Object>> filtered=new ArrayList<>();Map<String,Object> counts=map("all",0,"pending",0,"exact",0,"similar",0,"none",0,"flagged",0,"confirmed",0,"archived",0,"locked",0);
        for(Map<String,Object> row:reportRows(actor)){Map<String,Object> fields=identity(row.get("fields"));String date=str(row.get("examDate"));if(!channel.isEmpty()&&!channel.equals(row.get("channel")))continue;if(!from.isEmpty()&&(date.isEmpty()||date.compareTo(from)<0)||!to.isEmpty()&&(date.isEmpty()||date.compareTo(to)>0))continue;
            if(!search.isEmpty()&&!norm(row.get("fileName")).contains(search)&&!norm(fields.get("full_name")).contains(search)&&!norm(fields.get("employee_number")).contains(search)&&!norm(fields.get("identity_number")).contains(search))continue;
            Map<String,Object> output=enrich(row,history.get(row.get("id")+":"+row.get("revision")),people);String state=str(output.get("matchStatus"));boolean pending=!Arrays.asList("confirmed","archived","locked").contains(state);counts.put("all",num(counts.get("all"))+1);counts.put(state,num(counts.get(state))+1);if(pending)counts.put("pending",num(counts.get("pending"))+1);
            if(status.isEmpty()||status.equals("all")||status.equals(state)||status.equals("pending")&&pending||status.equals("matched")&&Arrays.asList("confirmed","archived").contains(state))filtered.add(output);
        }
        int page=bounded(query.get("page"),1,1,100000),limit=bounded(query.get("limit"),10,1,100),start=Math.min(filtered.size(),(page-1)*limit),end=Math.min(filtered.size(),start+limit);
        return map("items",filtered.subList(start,end),"total",filtered.size(),"page",page,"limit",limit,"counts",counts,"ruleVersion",RULE);
    }
    public Map<String,Object> detail(EhrActor actor,String id,int revision){ehr.rawReport(actor,id,revision,false);Map<String,Object> row=reportRows(actor).stream().filter(r->id.equals(r.get("id"))&&num(r.get("revision"))==revision).findFirst().orElseThrow(()->new EhrException(409,"报告已有新版本，请刷新列表"));Map<String,Object> result=enrich(row,saved(actor,id,revision,false),preparedEmployees(actor));
        Map<String,Object> report=ehr.report(actor,id,revision,false);result.put("files",report.get("files"));List<Map<String,Object>> logs=db.all("SELECT action,reason note,CONVERT(actor_ref USING utf8mb4) actor,occurred_at time,redacted_diff changes FROM a_health_archive_audit_logs WHERE scope_code=? AND data_mode=? AND report_id=? AND revision=? AND action LIKE 'report_match_%' ORDER BY occurred_at DESC,audit_id DESC LIMIT 100",actor.scope,actor.mode,id,revision);for(Map<String,Object> log:logs)log.put("changes",ehr.decode(log.get("changes")));result.put("logs",logs);result.put("ruleVersion",RULE);return result;
    }
    @Transactional public Map<String,Object> save(EhrActor actor,String id,int revision,String expected,Map<String,Object> body){
        require(!actor.mobile,403,"仅供后台管理使用");String action=text(body,"action"),target=text(body,"recordId"),reason=text(body,"reason"),requestKey=text(body,"requestKey");require(Arrays.asList("selection","confirm","unmatched","flag").contains(action),422,"操作类型不正确");require(!requestKey.isEmpty()&&requestKey.length()<=96,422,"缺少幂等键");require(!reason.isEmpty()&&reason.length()<=600,422,"请填写600字以内核对说明");
        Map<String,Object> raw=ehr.rawReport(actor,id,revision,false);String old=str(raw.get("record_id"));List<String> locks=new ArrayList<>(Arrays.asList(old));if(!target.isEmpty()&&!target.equals(old))locks.add(target);Collections.sort(locks);for(String record:locks)ehr.profile(actor,record,true);
        raw=ehr.rawReport(actor,id,revision,true);Map<String,Object> series=db.one("SELECT current_revision FROM a_report_series WHERE report_id=? FOR UPDATE",id);require(num(series.get("current_revision"))==revision,409,"报告已有新版本");Map<String,Object> prior=saved(actor,id,revision,true);String hash=hex(digest(bytes(ehr.encode(body))));if(prior!=null&&requestKey.equals(prior.get("last_request_key"))){require(hash.equals(prior.get("last_payload_sha256")),409,"幂等键不可复用于不同操作");return detail(actor,id,revision);}
        Map<String,Object> current=detail(actor,id,revision);require(!Boolean.TRUE.equals(current.get("locked")),409,"已审核或归档报告不能更改匹配，请通过修订流程处理");require(expected!=null&&expected.equals(current.get("etag")),409,"报告或匹配结果已变化，请刷新后重试");Map<String,Object> selected=null;
        if(action.equals("selection")||action.equals("confirm")){require(!target.isEmpty(),422,"请选择职工");selected=ehr.profile(actor,target,true);require(num(body.get("profileVersion"))==num(selected.get("row_version")),409,"职工资料已变化，请重新选择");}
        if(action.equals("confirm")){
            require(Boolean.TRUE.equals(body.get("identityVerified")),422,"请确认已对照原件核验职工身份");require(db.count("SELECT COUNT(*) FROM a_ocr_dispatch_tasks q JOIN a_extraction_jobs j ON j.job_id=q.job_id WHERE j.report_id=? AND q.dispatch_state IN ('queued','running','retry_wait')",id)==0,409,"报告仍在识别中，请等待结果稳定后核对");
            Map<String,Object> fields=identity(raw.get("field_values"));boolean nameMatches=!norm(fields.get("full_name")).isEmpty()&&norm(fields.get("full_name")).equals(norm(selected.get("employee_name")));
            boolean identifierConflict=(!norm(fields.get("employee_number")).isEmpty()&&!norm(fields.get("employee_number")).equals(norm(selected.get("employee_no"))))||(!norm(fields.get("phone")).isEmpty()&&!norm(fields.get("phone")).equals(norm(selected.get("phone"))));
            if(!nameMatches||identifierConflict||!((List<?>)fields.get("conflicts")).isEmpty())require(Boolean.TRUE.equals(body.get("override"))&&reason.length()>=10,422,"报告身份存在缺失或冲突，需勾选人工核验并填写至少10字依据");
            if(!target.equals(old)){
                require(actor.doctor,403,"报告改绑其他职工需医生权限");require(Boolean.TRUE.equals(body.get("allowRebind")),422,"请明确确认更改现有关联职工");require(db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=?",id)==0&&db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",id)==0,409,"有历史审核或归档版本的报告不能改绑");
                require(db.count("SELECT COUNT(*) FROM a_digital_worker_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND task_status IN ('queued','in_progress','pending_review')",actor.scope,actor.mode,old)==0,409,"原职工仍有进行中的数字员工任务，请先处理后再改绑");ehr.cancelOcrTasks(id,revision,"人工核验更改报告职工关联");db.exec("UPDATE a_health_reports SET record_id=? WHERE report_id=? AND revision=?",target,id,revision);ehr.completeness(actor,old);ehr.completeness(actor,target);
            }
        }
        String state=action.equals("confirm")?"confirmed":action.equals("flag")?"flagged":action;Map<String,Object> row=reportRows(actor).stream().filter(r->id.equals(r.get("id"))&&num(r.get("revision"))==revision).findFirst().get();String digest=fingerprint(row);int version=prior==null?1:num(prior.get("row_version"))+1;
        if(prior==null)db.insert("a_report_matching",ehr.scoped(actor,"report_id",id,"revision",revision,"matching_state",state,"selected_record_id",selected==null?null:target,"selected_profile_version",selected==null?null:selected.get("row_version"),"report_digest",digest,"rule_version",RULE,"row_version",version,"last_request_key",requestKey,"last_payload_sha256",hash,"updated_by",actor.user,"updated_at",now()));
        else db.exec("UPDATE a_report_matching SET matching_state=?,selected_record_id=?,selected_profile_version=?,report_digest=?,rule_version=?,row_version=?,last_request_key=?,last_payload_sha256=?,updated_by=?,updated_at=? WHERE scope_code=? AND data_mode=? AND report_id=? AND revision=?",state,selected==null?null:target,selected==null?null:selected.get("row_version"),digest,RULE,version,requestKey,hash,actor.user,now(),actor.scope,actor.mode,id,revision);
        db.insert("a_health_archive_audit_logs",ehr.scoped(actor,"audit_id",id(),"record_id",action.equals("confirm")?target:old,"report_id",id,"revision",revision,"actor_ref",bytes(actor.user),"action","report_match_"+action,"request_key",requestKey,"reason",reason,"redacted_diff",ehr.encode(map("beforeRecordId",old,"selectedRecordId",selected==null?null:target,"bindingChanged",action.equals("confirm")&&!old.equals(target),"state",state,"ruleVersion",RULE,"identityVerified",Boolean.TRUE.equals(body.get("identityVerified")))),"occurred_at",now()));return detail(actor,id,revision);
    }
}
